from term import Atom

class Atoms:
    def __getattr__(self, atom_name):
        atom_instance = Atom(atom_name)
        setattr(self, atom_name, atom_instance)
        return atom_instance

class CommandStartedMsg:
    pass

class EventMsg:
    pass

class CommandStatusMsg:
    pass
